@Composable
fun RepeatIntervalCountStepper(
    interval: RepeatInterval,
    count: Int,
    onCountChange: (Int) -> Unit
) {
    val countLabel = when (interval) {
        RepeatInterval.DAILY -> pluralStringResource(R.plurals.repeat_count_days, count, count)
        RepeatInterval.WEEKLY -> pluralStringResource(R.plurals.repeat_count_weeks, count, count)
        RepeatInterval.MONTHLY -> pluralStringResource(R.plurals.repeat_count_months, count, count)
        RepeatInterval.NONE -> return
    }
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(stringResource(R.string.repeat_every_label), fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurface)
            Text(
                countLabel,
                fontSize = 11.sp,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
            )
        }
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            val accent = MaterialTheme.colorScheme.primary
            @Composable
            fun StepButton(label: String, enabled: Boolean, onClick: () -> Unit) {
                Box(
                    modifier = Modifier
                        .size(32.dp)
                        .clip(CircleShape)
                        .background(if (enabled) accent.copy(alpha = 0.15f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                        .then(if (enabled) Modifier.clickable(onClick = onClick) else Modifier),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        label,
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = if (enabled) accent else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.3f)
                    )
                }
            }
            StepButton("-", enabled = count > 1) { onCountChange((count - 1).coerceAtLeast(1)) }
            Text("$count", fontWeight = FontWeight.Bold, fontSize = 14.sp, modifier = Modifier.width(20.dp), textAlign = TextAlign.Center)
            StepButton("+", enabled = count < 30) { onCountChange((count + 1).coerceAtMost(30)) }
        }
    }
}
